"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["54131"],{3717(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.formatos_permitidos.obrigatorio","status":422,"titulo":"FormatosPermitidos \xe9 obrigat\xf3rio: declare QUALQUER ou uma lista com ao menos um formato"},"descricao":{"codigo":"uniplus.selecao.formatos_permitidos.obrigatorio","requisitos":["UNI-REQ-0066"],"oQueAconteceu":["Toda exig\xeancia documental declara os formatos de arquivo que aceita: ou o token `QUALQUER`, ou uma\\nlista com ao menos um formato. A exig\xeancia enviada deixou `formatosPermitidos` ausente, nulo ou\\ncomo uma lista vazia. N\xe3o declarar nada n\xe3o vale como `QUALQUER`: a aceita\xe7\xe3o de qualquer formato\\n\xe9 uma declara\xe7\xe3o expl\xedcita.","A confer\xeancia acontece na montagem de cada exig\xeancia, depois das confer\xeancias do tipo de\\ndocumento, das condi\xe7\xf5es e das bases legais, e depois da idade m\xe1xima de emiss\xe3o; a do modelo\\ncitado vem em seguida. A \xe1rvore de exig\xeancias para no primeiro n\xf3 com defeito.","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz exig\xeancia sem formatos,\\nporque a defini\xe7\xe3o a recusa antes. Nessas leituras a recusa se refere \xe0 vers\xe3o congelada, n\xe3o ao\\npedido enviado."],"comoResolver":["Declare `formatosPermitidos` na exig\xeancia como:","- o texto `QUALQUER`, se qualquer formato \xe9 aceito; ou\\n- uma lista com ao menos um formato (`PDF`, `JPEG` ou `PNG`).","Depois, envie a defini\xe7\xe3o de novo.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir os documentos exigidos do\\nprocesso n\xe3o a corrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Consulta do formul\xe1rio renderiz\xe1vel do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, submiss\xe3o, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Formatos permitidos"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);